window.TK_DATA = {"id":"tk","title":"ТК РО","full_title":"ТРУДОВОЙ КОДЕКС РО","revision":"25.08.2026","source_url":"https://forum.russia.online/threads/trudovoi-kodeks-ro.4943/","post_id":"post-16520","preamble":"Настоящий Кодекс устанавливает основные принципы регулирования труда в РО, права и обязанности работников и работодателей, порядок возникновения, изменения, приостановления и прекращения трудовых отношений, правила рабочего времени и отдыха, основы оплаты и охраны труда, дисциплинарной и материальной ответственности, а также порядок защиты трудовых прав.","signature":"Нормативно-правовой акт подписан Премьер-министром РО 27.09.2026 Марк Брагин ​","type_detected":"A","nodes":[{"type":"section","number":"I","title":"ОБЩИЕ ПОЛОЖЕНИЯ","children":[{"type":"chapter","number":"I","title":"ОСНОВЫ ТРУДОВОГО ЗАКОНОДАТЕЛЬСТВА​","children":[{"type":"article","number":"1","title":"Цели трудового законодательства","children":[{"type":"paragraph","number":"1","text":"Целями трудового законодательства являются обеспечение свободы труда, установление государственных гарантий трудовых прав, создание справедливых и безопасных условий труда, защита законных интересов работников и работодателей."},{"type":"paragraph","number":"2","text":"Трудовое законодательство должно обеспечивать разумный баланс интересов работника, работодателя и государства."}]},{"type":"article","number":"2","title":"Основные принципы регулирования труда","children":[{"type":"paragraph","text":"Основными принципами регулирования трудовых отношений являются:","children":[{"type":"subparagraph","number":"1","text":"свобода труда и свобода выбора рода деятельности;"},{"type":"subparagraph","number":"2","text":"запрещение принудительного труда;"},{"type":"subparagraph","number":"3","text":"запрещение дискриминации в сфере труда;"},{"type":"subparagraph","number":"4","text":"равенство работников перед законом;"},{"type":"subparagraph","number":"5","text":"право на своевременную и полную оплату труда;"},{"type":"subparagraph","number":"6","text":"право на отдых и безопасные условия труда;"},{"type":"subparagraph","number":"7","text":"обязательность исполнения законного трудового договора;"},{"type":"subparagraph","number":"8","text":"недопустимость произвольного увольнения в обычных трудовых отношениях с учетом специальных кадровых полномочий, установленных федеральным законодательством;"},{"type":"subparagraph","number":"9","text":"право на защиту трудовых прав и разрешение трудового спора;"},{"type":"subparagraph","number":"10","text":"сочетание государственного и договорного регулирования труда."}]}]},{"type":"article","number":"3","title":"Сфера действия настоящего Кодекса","children":[{"type":"paragraph","number":"1","text":"Настоящий Кодекс применяется к трудовым отношениям на территории РО независимо от формы собственности работодателя."},{"type":"paragraph","number":"2","text":"Настоящий Кодекс применяется к государственным служащим в части, не урегулированной Федеральным законом «О государственной службе РО», профильными федеральными законами и законодательством о специальном статусе соответствующего должностного лица."},{"type":"paragraph","number":"3","text":"При противоречии общей нормы настоящего Кодекса специальной норме федерального закона, регулирующей государственную, военную, правоохранительную или иную специальную службу, применяется специальная норма."},{"type":"paragraph","number":"4","text":"Положения настоящего Кодекса о приеме на работу, переводе, дисциплинарной ответственности, основаниях увольнения и восстановлении на работе не ограничивают специальные кадровые полномочия Премьер-министра РО, Вице Премьер-министра РО, федеральных министров и иных должностных лиц, которым федеральным законодательством предоставлено право свободного назначения на государственную должность и освобождения от нее."},{"type":"paragraph","number":"5","text":"Назначение на государственную должность и освобождение от государственной должности актом Премьер-министра РО, Вице Премьер-министра РО либо иного уполномоченного федеральным законодательством должностного лица не признается обычным приемом на работу или увольнением по инициативе работодателя, если соответствующая должность замещается в специальном порядке."}]},{"type":"article","number":"4","title":"Источники трудового права","children":[{"type":"paragraph","number":"1","text":"Трудовые отношения регулируются Конституцией РО, настоящим Кодексом, федеральными законами, нормативными актами Премьер-министра и Правительства РО, принятыми в пределах их компетенции, а также законными локальными актами работодателя и трудовыми договорами."},{"type":"paragraph","number":"2","text":"Локальный акт работодателя не может ухудшать положение работника по сравнению с настоящим Кодексом и актами большей юридической силы."},{"type":"paragraph","number":"3","text":"Условие трудового договора, уменьшающее установленные законом гарантии работника, применению не подлежит в соответствующей части."}]},{"type":"article","number":"5","title":"Запрещение дискриминации в сфере труда","children":[{"type":"paragraph","number":"1","text":"Каждый имеет равные возможности для реализации трудовых прав."},{"type":"paragraph","number":"2","text":"Запрещается необоснованно ограничивать трудовые права или предоставлять преимущества по признакам пола, расы, национальности, происхождения, убеждений, имущественного или должностного положения и иным обстоятельствам, не связанным с деловыми качествами лица или законными требованиями к соответствующей работе."},{"type":"paragraph","number":"3","text":"Не является дискриминацией установление требований, объективно обусловленных характером работы, состоянием здоровья, необходимой квалификацией, допуском к охраняемой законом тайне, требованиями государственной безопасности или специальным статусом должности."},{"type":"paragraph","number":"4","text":"Лицо, считающее себя подвергнутым дискриминации, вправе обратиться к работодателю, в прокуратуру или в суд."}]},{"type":"article","number":"6","title":"Запрещение принудительного труда","children":[{"type":"paragraph","number":"1","text":"Принудительным трудом признается выполнение работы под угрозой незаконного наказания, насилия, удержания имущества или иного неправомерного воздействия."},{"type":"paragraph","number":"2","text":"Не является принудительным трудом работа, обязанность выполнения которой прямо предусмотрена федеральным законом в условиях чрезвычайного или военного положения, при устранении непосредственной угрозы жизни и безопасности населения, при исполнении вступившего в силу судебного акта либо в иных прямо установленных законом случаях."},{"type":"paragraph","number":"3","text":"Законная дисциплинарная обязанность военнослужащего или сотрудника специальной службы, установленная федеральным законом, не является принудительным трудом."}]},{"type":"article","number":"7","title":"Локальные акты работодателя","children":[{"type":"paragraph","number":"1","text":"Работодатель вправе принимать правила внутреннего трудового распорядка, должностные инструкции, положения об отделах, правила премирования и иные локальные акты."},{"type":"paragraph","number":"2","text":"Работник должен иметь разумную возможность ознакомиться с локальными актами, непосредственно относящимися к его работе."},{"type":"paragraph","number":"3","text":"Локальный акт не может предоставлять работодателю публичные полномочия, которыми он не наделен федеральным законодательством."},{"type":"paragraph","number":"4","text":"При выявлении противоречия локального акта закону применяется закон, а противоречащая норма локального акта не подлежит применению."}]},{"type":"article","number":"8","title":"Исчисление сроков","children":[{"type":"paragraph","number":"1","text":"Срок, определенный днями, неделями или месяцами, исчисляется в календарном времени, если настоящим Кодексом прямо не установлено иное."},{"type":"paragraph","number":"2","text":"Если последний день срока приходится на период, когда выполнение необходимого действия объективно невозможно вследствие режима работы организации, срок переносится на ближайший рабочий период."},{"type":"paragraph","number":"3","text":"Специальный федеральный закон может устанавливать иной порядок исчисления сроков для государственной или военной службы."}]},{"type":"article","number":"9","title":"Государственная политика и надзор в сфере труда","children":[{"type":"paragraph","number":"1","text":"Правительство РО обеспечивает проведение государственной политики в сфере труда и общую организацию государственного контроля за соблюдением трудового законодательства."},{"type":"paragraph","number":"2","text":"Прокуратура РО осуществляет надзор за исполнением трудового законодательства в формах, предусмотренных федеральным законодательством."},{"type":"paragraph","number":"3","text":"Суд осуществляет защиту трудовых прав и разрешает трудовые споры в пределах своей компетенции."},{"type":"paragraph","number":"4","text":"Государственный контроль не может использоваться для произвольного вмешательства в законную хозяйственную деятельность работодателя."}]}]}]},{"type":"section","number":"II","title":"ТРУДОВЫЕ ОТНОШЕНИЯ И ТРУДОВОЙ ДОГОВОР","children":[{"type":"chapter","number":"II","title":"СТОРОНЫ ТРУДОВЫХ ОТНОШЕНИЙ​","children":[{"type":"article","number":"10","title":"Понятие трудовых отношений","children":[{"type":"paragraph","text":"Трудовыми отношениями являются отношения, основанные на личном выполнении работником за вознаграждение определенной трудовой функции в интересах, под управлением или контролем работодателя при обеспечении работодателем предусмотренных законом условий труда."}]},{"type":"article","number":"11","title":"Работник и работодатель","children":[{"type":"paragraph","number":"1","text":"Работником является физическое лицо, вступившее в трудовые отношения с работодателем."},{"type":"paragraph","number":"2","text":"Работодателем является физическое лицо, юридическое лицо, государственный орган, государственная организация либо иной субъект, которому законом предоставлено право принимать работников."},{"type":"paragraph","number":"3","text":"От имени работодателя права и обязанности осуществляет руководитель либо иное уполномоченное им или законом должностное лицо."},{"type":"paragraph","number":"4","text":"Непосредственный руководитель работника обладает полномочиями работодателя только в пределах предоставленной ему кадровой и дисциплинарной компетенции."}]},{"type":"article","number":"12","title":"Основные права работника","children":[{"type":"paragraph","text":"Работник имеет право:","children":[{"type":"subparagraph","number":"1","text":"на заключение, изменение и прекращение трудового договора в установленном законом порядке;"},{"type":"subparagraph","number":"2","text":"на предоставление обусловленной работы;"},{"type":"subparagraph","number":"3","text":"на своевременную и полную оплату труда;"},{"type":"subparagraph","number":"4","text":"на безопасные условия труда;"},{"type":"subparagraph","number":"5","text":"на отдых в соответствии с настоящим Кодексом и локальными актами;"},{"type":"subparagraph","number":"6","text":"на получение необходимой для работы информации и средств;"},{"type":"subparagraph","number":"7","text":"на уважение чести и достоинства;"},{"type":"subparagraph","number":"8","text":"на отказ от явно незаконного требования работодателя;"},{"type":"subparagraph","number":"9","text":"на обжалование незаконного взыскания, отстранения, перевода или увольнения;"},{"type":"subparagraph","number":"10","text":"на защиту трудовых прав всеми не запрещенными законом способами."}]}]},{"type":"article","number":"13","title":"Основные обязанности работника","children":[{"type":"paragraph","text":"Работник обязан:","children":[{"type":"subparagraph","number":"1","text":"добросовестно исполнять трудовые обязанности;"},{"type":"subparagraph","number":"2","text":"соблюдать законные правила внутреннего трудового распорядка;"},{"type":"subparagraph","number":"3","text":"соблюдать требования безопасности и охраны труда;"},{"type":"subparagraph","number":"4","text":"бережно относиться к имуществу работодателя и иных работников;"},{"type":"subparagraph","number":"5","text":"исполнять законные распоряжения уполномоченного руководителя;"},{"type":"subparagraph","number":"6","text":"незамедлительно сообщать о ситуации, создающей непосредственную угрозу жизни, здоровью или существенному имуществу;"},{"type":"subparagraph","number":"7","text":"сохранять охраняемую законом или договором тайну;"},{"type":"subparagraph","number":"8","text":"соблюдать иные обязанности, прямо предусмотренные федеральным законодательством или трудовым договором."}]}]},{"type":"article","number":"14","title":"Основные права работодателя","children":[{"type":"paragraph","text":"Работодатель вправе:","children":[{"type":"subparagraph","number":"1","text":"заключать, изменять и расторгать трудовые договоры;"},{"type":"subparagraph","number":"2","text":"требовать исполнения трудовых обязанностей и соблюдения законных локальных актов;"},{"type":"subparagraph","number":"3","text":"контролировать качество и результат работы;"},{"type":"subparagraph","number":"4","text":"поощрять работников;"},{"type":"subparagraph","number":"5","text":"применять дисциплинарные меры в установленном законом порядке;"},{"type":"subparagraph","number":"6","text":"требовать возмещения прямого действительного ущерба при наличии законных оснований;"},{"type":"subparagraph","number":"7","text":"принимать локальные нормативные акты в пределах своей компетенции."}]}]},{"type":"article","number":"15","title":"Основные обязанности работодателя","children":[{"type":"paragraph","text":"Работодатель обязан:","children":[{"type":"subparagraph","number":"1","text":"соблюдать трудовое законодательство и условия трудового договора;"},{"type":"subparagraph","number":"2","text":"предоставить работнику обусловленную работу;"},{"type":"subparagraph","number":"3","text":"обеспечить безопасные условия труда и необходимые средства;"},{"type":"subparagraph","number":"4","text":"своевременно и в полном объеме выплачивать вознаграждение;"},{"type":"subparagraph","number":"5","text":"знакомить работника с относящимися к нему локальными актами;"},{"type":"subparagraph","number":"6","text":"не допускать дискриминации и унижающего достоинство обращения;"},{"type":"subparagraph","number":"7","text":"исполнять законные судебные акты и акты государственного надзора;"},{"type":"subparagraph","number":"8","text":"рассматривать обращения работника по вопросам его трудовых прав;"},{"type":"subparagraph","number":"9","text":"обеспечивать хранение кадровых документов и сведений, если такое хранение требуется законом."}]}]}]},{"type":"chapter","number":"III","title":"ЗАКЛЮЧЕНИЕ, ИЗМЕНЕНИЕ, ПРИОСТАНОВЛЕНИЕ И ПРЕКРАЩЕНИЕ ТРУДОВОГО ДОГОВОРА​","children":[{"type":"article","number":"16","title":"Понятие трудового договора","children":[{"type":"paragraph","number":"1","text":"Трудовой договор — соглашение между работником и работодателем, по которому работник обязуется лично выполнять определенную трудовую функцию, а работодатель — предоставить работу, обеспечить законные условия труда и выплачивать вознаграждение."},{"type":"paragraph","number":"2","text":"Трудовой договор может быть заключен в письменной, электронной либо иной форме."},{"type":"paragraph","number":"3","text":"Условия договора должны позволять определить работодателя, работника, трудовую функцию и основные условия оплаты труда."}]},{"type":"article","number":"17","title":"Документы при трудоустройстве","children":[{"type":"paragraph","number":"1","text":"Работодатель вправе потребовать документ, удостоверяющий личность, а также документы, объективно необходимые для соответствующей работы."},{"type":"paragraph","number":"2","text":"Для работы, требующей лицензии, медицинского заключения, допуска к государственной тайне, военного билета или иной специальной квалификации, работодатель вправе требовать подтверждающий документ."},{"type":"paragraph","number":"3","text":"Для поступления на государственную службу применяются специальные требования Федерального закона «О государственной службе РО» и профильного законодательства."},{"type":"paragraph","number":"4","text":"Работодатель не вправе требовать документы, не связанные с трудовой функцией и не предусмотренные законом или объективной необходимостью."}]},{"type":"article","number":"18","title":"Возникновение трудовых отношений","children":[{"type":"paragraph","number":"1","text":"Трудовые отношения возникают с момента заключения трудового договора либо фактического допуска лица к работе уполномоченным представителем работодателя."},{"type":"paragraph","number":"2","text":"Фактический допуск к работе не освобождает работодателя от обязанности оформить трудовые отношения."},{"type":"paragraph","number":"3","text":"Допуск к работе лицом, не имеющим кадровых полномочий, сам по себе не создает обязанности работодателя, если работодатель не подтвердил или фактически не принял такую работу."}]},{"type":"article","number":"19","title":"Испытание и стажировка","children":[{"type":"paragraph","number":"1","text":"При поступлении на работу может устанавливаться испытание или стажировка, если это предусмотрено локальным актом или трудовым договором."},{"type":"paragraph","number":"2","text":"До начала испытания работник должен быть уведомлен об основных критериях его прохождения."},{"type":"paragraph","number":"3","text":"Неуспешное прохождение испытания может являться основанием прекращения трудовых отношений, если решение основано на фактических результатах и не носит дискриминационного характера."},{"type":"paragraph","number":"4","text":"Для государственной службы специальные правила испытания и академии могут определяться профильным законодательством и внутренними актами."}]},{"type":"article","number":"20","title":"Изменение условий труда","children":[{"type":"paragraph","number":"1","text":"Существенное изменение трудовой функции, постоянный перевод на другую должность или уменьшение согласованного вознаграждения допускаются с согласия работника, если иное прямо не предусмотрено федеральным законом."},{"type":"paragraph","number":"2","text":"Временное изменение обязанностей допускается при служебной или производственной необходимости в пределах квалификации работника и разумного срока."},{"type":"paragraph","number":"3","text":"Изменение условий не может использоваться как скрытая дисциплинарная мера в обход установленного порядка."}]},{"type":"article","number":"21","title":"Перевод","children":[{"type":"paragraph","number":"1","text":"Переводом признается постоянное изменение трудовой функции или работодателя с сохранением непрерывности трудовых отношений."},{"type":"paragraph","number":"2","text":"Перевод между работодателями производится с согласия работника и принимающей стороны."},{"type":"paragraph","number":"3","text":"Для государственных служащих применяются также правила главы VIII настоящего Кодекса и специального законодательства."}]},{"type":"article","number":"22","title":"Временное отстранение от работы","children":[{"type":"paragraph","number":"1","text":"Работник может быть временно отстранен от исполнения обязанностей при наличии законного основания."},{"type":"paragraph","number":"2","text":"Отстранение не является признанием вины и само по себе не считается дисциплинарным взысканием."},{"type":"paragraph","number":"3","text":"Основаниями отстранения могут являться:","children":[{"type":"subparagraph","number":"1","text":"отсутствие обязательной лицензии, допуска или медицинского заключения;"},{"type":"subparagraph","number":"2","text":"состояние опьянения;"},{"type":"subparagraph","number":"3","text":"непосредственная угроза безопасности;"},{"type":"subparagraph","number":"4","text":"необходимость предотвратить уничтожение доказательств, давление на участников проверки или существенный служебный риск;"},{"type":"subparagraph","number":"5","text":"вступивший в силу судебный акт либо законное требование компетентного государственного органа;"},{"type":"subparagraph","number":"6","text":"иное основание, прямо установленное федеральным законом."}]},{"type":"paragraph","number":"4","text":"Отстранение прекращается после отпадения его основания, если отсутствует самостоятельное основание для прекращения трудовых отношений."}]},{"type":"article","number":"23","title":"Общие основания прекращения трудового договора","children":[{"type":"paragraph","text":"Трудовой договор прекращается:","children":[{"type":"subparagraph","number":"1","text":"по соглашению сторон;"},{"type":"subparagraph","number":"2","text":"по инициативе работника;"},{"type":"subparagraph","number":"3","text":"по инициативе работодателя на законном основании;"},{"type":"subparagraph","number":"4","text":"в связи с истечением срока срочного договора;"},{"type":"subparagraph","number":"5","text":"при переводе к другому работодателю;"},{"type":"subparagraph","number":"6","text":"в связи с невозможностью продолжения работы по объективным медицинским или юридическим основаниям;"},{"type":"subparagraph","number":"7","text":"по вступившему в силу судебному акту;"},{"type":"subparagraph","number":"8","text":"по иным основаниям, прямо предусмотренным федеральным законом;"},{"type":"subparagraph","number":"9","text":"в связи с освобождением от государственной должности компетентным должностным лицом в порядке, установленном федеральным конституционным законом или федеральным законом."}]}]},{"type":"article","number":"24","title":"Прекращение договора по инициативе работника","children":[{"type":"paragraph","number":"1","text":"Работник вправе прекратить трудовые отношения по собственному желанию, уведомив работодателя способом, позволяющим подтвердить волеизъявление."},{"type":"paragraph","number":"2","text":"Работодатель не вправе необоснованно удерживать работника на работе против его воли."},{"type":"paragraph","number":"3","text":"При наличии у работника незавершенной передачи имущества, документов или дел работодатель вправе потребовать совершить разумные действия по передаче, но не вправе использовать это как основание бессрочного отказа в увольнении."},{"type":"paragraph","number":"4","text":"Специальный закон может устанавливать особый порядок увольнения со службы или сдачи государственного имущества."}]},{"type":"article","number":"25","title":"Прекращение договора по инициативе работодателя","children":[{"type":"paragraph","number":"1","text":"Работодатель вправе прекратить трудовые отношения при наличии одного из следующих оснований:","children":[{"type":"subparagraph","number":"1","text":"неоднократное виновное неисполнение трудовых обязанностей после применения дисциплинарной меры;"},{"type":"subparagraph","number":"2","text":"однократное грубое нарушение трудовых обязанностей;"},{"type":"subparagraph","number":"3","text":"прогул без уважительной причины;"},{"type":"subparagraph","number":"4","text":"появление на работе в состоянии алкогольного или наркотического опьянения;"},{"type":"subparagraph","number":"5","text":"умышленное причинение существенного ущерба работодателю;"},{"type":"subparagraph","number":"6","text":"разглашение охраняемой законом или договором тайны;"},{"type":"subparagraph","number":"7","text":"насилие, хищение или иное тяжкое противоправное деяние на рабочем месте, если факт установлен в предусмотренном законом порядке;"},{"type":"subparagraph","number":"8","text":"непрохождение испытания или обязательной аттестации;"},{"type":"subparagraph","number":"9","text":"утрата обязательной лицензии, допуска или медицинской пригодности, без которых продолжение работы невозможно;"},{"type":"subparagraph","number":"10","text":"ликвидация работодателя или фактическое прекращение соответствующей должности;"},{"type":"subparagraph","number":"11","text":"низкая трудовая активность;"},{"type":"subparagraph","number":"12","text":"иное основание, прямо установленное федеральным законом."}]},{"type":"paragraph","number":"2","text":"Само по себе задержание, подозрение, обвинение, проведение проверки или нахождение лица в розыске не означает доказанность трудового проступка и не влечет автоматического увольнения, если федеральным законом прямо не предусмотрено иное."},{"type":"paragraph","number":"3","text":"Утрата доверия может являться основанием увольнения без дополнительного объяснения причины в органах Правительства, прокуратуры, Следственного комитета и Федеральной службы безопасности в силу обеспечения интересов национальной безопасности и особого статуса службы в данных органах."},{"type":"paragraph","number":"4","text":"Основания, предусмотренные частью 1 настоящей статьи, не ограничивают специальные кадровые полномочия Премьер-министра РО, Вице Премьер-министра РО, федерального министра либо иного должностного лица, которому федеральным законодательством предоставлено право свободного назначения на государственную должность и освобождения от нее."},{"type":"paragraph","number":"5","text":"Если федеральным законодательством должность отнесена к числу замещаемых по специальному назначению, уполномоченное должностное лицо вправе освободить занимающее ее лицо без предварительного дисциплинарного взыскания, служебной проверки, доказанности дисциплинарного проступка или указания одного из оснований, перечисленных в части 1 настоящей статьи."},{"type":"paragraph","number":"6","text":"Такое освобождение является самостоятельным кадровым решением и не считается дисциплинарным взысканием, если в акте об освобождении прямо не указано иное."},{"type":"note","text":"Под низкой трудовой активностью понимается отсутствие сотрудника на рабочем месте, а также за пределами РО на протяжении более трёх дней подряд, за исключением случаев согласованного отпуска или отгула."}]},{"type":"article","number":"25.1","title":"Прекращение действия трудового договора по инициативе органов государственного надзора","children":[{"type":"subparagraph","number":"1","text":"Трудовые отношение могут быть прекращены сотрудником органов государственного надзора в следующих случаях:"},{"type":"subparagraph","number":"А","text":"подтвержденного факта нарушения работником законодательства РО;"},{"type":"subparagraph","number":"Б","text":"участия работника в экстремистских и иных незаконных формированиях;"},{"type":"subparagraph","number":"В","text":"непройденной работником проверки от органов государственного надзора;"}]},{"type":"article","number":"26","title":"Однократное грубое нарушение","children":[{"type":"paragraph","text":"К однократному грубому нарушению могут относиться:","children":[{"type":"subparagraph","number":"1","text":"умышленный отказ исполнять законную обязанность, повлекший существенные последствия;"},{"type":"subparagraph","number":"2","text":"применение насилия к работнику, клиенту или гражданину в связи с работой;"},{"type":"subparagraph","number":"3","text":"хищение или умышленное уничтожение имущества;"},{"type":"subparagraph","number":"4","text":"грубое нарушение требований безопасности, создавшее реальную угрозу жизни или тяжкого вреда;"},{"type":"subparagraph","number":"5","text":"умышленное разглашение государственной, служебной, коммерческой или иной охраняемой законом тайны;"},{"type":"subparagraph","number":"6","text":"использование должности для получения незаконной выгоды;"},{"type":"subparagraph","number":"7","text":"иное нарушение, которое по характеру и последствиям делает продолжение трудовых отношений явно невозможным."}]}]},{"type":"article","number":"27","title":"Оформление прекращения и восстановление","children":[{"type":"paragraph","number":"1","text":"Решение об увольнении должно исходить от компетентного лица и содержать основание."},{"type":"paragraph","number":"2","text":"По требованию работника работодатель обязан сообщить причину увольнения и предоставить относящиеся к нему документы, если их выдача не нарушает охраняемую законом тайну."},{"type":"paragraph","number":"3","text":"Незаконное увольнение может быть отменено работодателем, вышестоящим органом в пределах его компетенции либо судом."},{"type":"paragraph","number":"4","text":"При отмене незаконного увольнения работник подлежит восстановлению, если это объективно возможно и отсутствует другое самостоятельное законное основание для прекращения отношений."},{"type":"paragraph","number":"5","text":"Вопрос о компенсации за незаконное лишение возможности трудиться разрешается по соглашению сторон или судом."},{"type":"paragraph","number":"6","text":"Лицо, освобожденное от государственной должности в порядке специального кадрового полномочия Премьер-министра РО, Вице Премьер-министра РО или иного уполномоченного законом должностного лица, не подлежит восстановлению на этой должности только по мотиву отсутствия дисциплинарного проступка, недостаточности причин освобождения либо несогласия с политической или кадровой целесообразностью такого решения."},{"type":"paragraph","number":"7","text":"Судебному или иному предусмотренному законом контролю могут подлежать наличие полномочия на освобождение, соблюдение обязательной процедуры и соответствие акта Конституции РО и федеральному законодательству, но не сама кадровая целесообразность решения, если закон предоставляет соответствующему должностному лицу право свободного освобождения от должности."}]}]}]},{"type":"section","number":"III","title":"РАБОЧЕЕ ВРЕМЯ И ВРЕМЯ ОТДЫХА","children":[{"type":"chapter","number":"IV","title":"РАБОЧЕЕ ВРЕМЯ, ПЕРЕРЫВЫ И ОТПУСКА​","children":[{"type":"article","number":"28","title":"Рабочее время","children":[{"type":"paragraph","text":"Рабочим временем признается период, в течение которого работник обязан находиться на рабочем месте либо выполнять трудовые обязанности в соответствии с трудовым договором, графиком или законным распоряжением работодателя."}]},{"type":"article","number":"29","title":"Режим рабочего времени","children":[{"type":"paragraph","number":"1","text":"Продолжительность и режим работы устанавливаются трудовым договором, графиком или правилами внутреннего трудового распорядка."},{"type":"paragraph","number":"2","text":"Работодатель обязан организовать режим труда таким образом, чтобы работник имел реальную возможность пользоваться предусмотренным настоящим Кодексом временем отдыха."},{"type":"paragraph","number":"3","text":"Работник вправе по собственной инициативе продолжать работу после завершения установленного рабочего времени, если это не нарушает требования безопасности и не создает обязанности работодателя оплачивать время, которое не было им поручено или одобрено."}]},{"type":"article","number":"30","title":"Сверхурочная работа","children":[{"type":"paragraph","number":"1","text":"Сверхурочной признается работа сверх установленного для работника рабочего времени по поручению работодателя."},{"type":"paragraph","number":"2","text":"Привлечение к сверхурочной работе допускается с согласия работника, кроме чрезвычайной, оперативной или иной неотложной необходимости, прямо вытекающей из закона или характера государственной службы."},{"type":"paragraph","number":"3","text":"Сверхурочная работа не должна использоваться как постоянный способ замены нормального графика."}]},{"type":"article","number":"31","title":"Неполное рабочее время","children":[{"type":"paragraph","text":"По соглашению работника и работодателя может устанавливаться неполный рабочий день, неполная рабочая неделя или иной сокращенный режим труда."}]},{"type":"article","number":"32","title":"Время отдыха","children":[{"type":"paragraph","text":"Временем отдыха является время, в течение которого работник свободен от исполнения трудовых обязанностей и вправе использовать его по своему усмотрению, если иное не вытекает из режима специальной службы."}]},{"type":"article","number":"33","title":"Перерыв для отдыха и питания","children":[{"type":"paragraph","number":"1","text":"Работнику, непрерывно находившемуся на работе не менее двух часов, по его запросу предоставляется перерыв для отдыха и питания продолжительностью от одного до двух часов."},{"type":"paragraph","number":"2","text":"Конкретное время перерыва определяется с учетом работы организации и текущей служебной или производственной обстановки."},{"type":"paragraph","number":"3","text":"Сотрудник правоохранительного органа, ФСБ, Следственного комитета, Вооруженных Сил, медицинской организации или иной службы непрерывного реагирования может быть отозван с перерыва при реальной оперативной необходимости."},{"type":"paragraph","number":"4","text":"Отзыв с перерыва не должен использоваться систематически без объективной необходимости."}]},{"type":"article","number":"34","title":"Дополнительный перерыв при длительной работе","children":[{"type":"paragraph","number":"1","text":"Работник, фактически находившийся на работе более шести часов в течение одного рабочего периода, вправе запросить дополнительный перерыв продолжительностью до двух часов."},{"type":"paragraph","number":"2","text":"Работодатель или непосредственный руководитель вправе перенести либо не предоставить такой перерыв при наличии существенной производственной, оперативной или иной объективной необходимости."},{"type":"paragraph","number":"3","text":"Отказ должен быть связан с реальной необходимостью, а не использоваться как дисциплинарное воздействие."}]},{"type":"article","number":"35","title":"Отпуск","children":[{"type":"paragraph","number":"1","text":"Работник, завершивший обязательную стажировку или испытание, вправе на отпуск общей продолжительностью до семи календарных дней в течение одного календарного месяца."},{"type":"paragraph","number":"2","text":"Порядок подачи заявления и согласования дат определяется локальным актом."},{"type":"paragraph","number":"3","text":"Работодатель обязан предоставить отпуск в пределах установленной нормы, если отсутствует чрезвычайная производственная или служебная необходимость."},{"type":"paragraph","number":"4","text":"При невозможности предоставить отпуск в заявленный период работодатель обязан предложить разумный альтернативный период."},{"type":"paragraph","number":"5","text":"Дополнительный отпуск за выдающиеся результаты труда может предоставляться работодателем по своему усмотрению."}]},{"type":"article","number":"36","title":"Отзыв из отпуска","children":[{"type":"paragraph","number":"1","text":"Отзыв работника из уже начавшегося отпуска допускается с его согласия."},{"type":"paragraph","number":"2","text":"Для военнослужащих, сотрудников правоохранительных органов, ФСБ, Следственного комитета, экстренной медицинской службы и иных служб непрерывного реагирования специальный закон или режим чрезвычайной необходимости может предусматривать обязательный отзыв."},{"type":"paragraph","number":"3","text":"Неиспользованная часть отпуска сохраняется, если иное не предусмотрено специальным федеральным законом."}]}]}]},{"type":"section","number":"IV","title":"ОПЛАТА ТРУДА И ПООЩРЕНИЕ","children":[{"type":"chapter","number":"V","title":"ЗАРАБОТНАЯ ПЛАТА И ПРЕМИРОВАНИЕ​","children":[{"type":"article","number":"37","title":"Оплата труда","children":[{"type":"paragraph","number":"1","text":"Оплата труда производится в денежной форме в рублях РО, если федеральным законодательством не предусмотрено иное."},{"type":"paragraph","number":"2","text":"Размер и система оплаты определяются законом, трудовым договором, штатным расписанием, локальным актом либо иным законным основанием."},{"type":"paragraph","number":"3","text":"Оплата может включать фиксированную, почасовую, сдельную и премиальную составляющие."}]},{"type":"article","number":"38","title":"Срок выплаты заработной платы","children":[{"type":"paragraph","number":"1","text":"Заработная плата выплачивается своевременно и в полном объеме."},{"type":"paragraph","number":"2","text":"Если оплата труда производится периодическими выплатами, период между ними не должен превышать семи календарных дней, если иной порядок объективно установлен государственной системой финансирования или специальным законом."},{"type":"paragraph","number":"3","text":"Необоснованная задержка или невыплата заработной платы является нарушением трудового законодательства."}]},{"type":"article","number":"39","title":"Премирование","children":[{"type":"paragraph","number":"1","text":"Работодатель вправе премировать работников за добросовестный, эффективный или выдающийся труд."},{"type":"paragraph","number":"2","text":"Размер премии может зависеть от должности, квалификации, результатов работы, отработанного времени, сложности и особой значимости выполненной задачи."},{"type":"paragraph","number":"3","text":"Премия, не установленная как гарантированная часть оплаты труда, не является безусловным правом работника."},{"type":"paragraph","number":"4","text":"Премирование не может использоваться как форма оплаты незаконного действия, подкупа или скрытого вознаграждения за злоупотребление полномочиями."}]},{"type":"article","number":"40","title":"Премирование государственных организаций","children":[{"type":"paragraph","number":"1","text":"Правительство РО вправе осуществлять дополнительное финансирование и премирование государственных организаций в пределах государственного бюджета."},{"type":"paragraph","number":"2","text":"Основанием могут являться результаты работы, отчетность, выполнение государственных задач и иные объективные показатели."},{"type":"paragraph","number":"3","text":"Отсутствие требуемой отчетности или подтвержденных результатов может являться основанием для отказа в дополнительном премировании."},{"type":"paragraph","number":"4","text":"Порядок распределения бюджетного премирования определяется Правительством РО."}]},{"type":"article","number":"41","title":"Удержания из заработной платы","children":[{"type":"paragraph","number":"1","text":"Удержание денежных средств из заработной платы допускается только на основании закона, судебного акта, добровольного согласия работника либо заранее установленного и законного порядка материальной ответственности."},{"type":"paragraph","number":"2","text":"Работодатель не вправе произвольно назначать денежные штрафы как дисциплинарное взыскание, если такая мера прямо не предусмотрена федеральным законом."},{"type":"paragraph","number":"3","text":"Невыплата законно начисленной премии не считается штрафом, если премия не являлась гарантированной выплатой."}]},{"type":"article","number":"42","title":"Поощрения за труд","children":[{"type":"paragraph","text":"Работодатель вправе применять благодарность, грамоту, ценную награду, дополнительную премию, дополнительный отпуск, представление к государственной или ведомственной награде и иные законные формы поощрения."}]}]}]},{"type":"section","number":"V","title":"ОХРАНА ТРУДА","children":[{"type":"chapter","number":"VI","title":"БЕЗОПАСНОСТЬ И ЗДОРОВЬЕ РАБОТНИКОВ​","children":[{"type":"article","number":"43","title":"Право на безопасный труд","children":[{"type":"paragraph","number":"1","text":"Работник имеет право на рабочее место и условия труда, не создающие необоснованной угрозы его жизни и здоровью."},{"type":"paragraph","number":"2","text":"Особенности работы, по самой природе связанной с риском, определяются специальным законодательством и должностными обязанностями."}]},{"type":"article","number":"44","title":"Обязанности работодателя в сфере охраны труда","children":[{"type":"paragraph","text":"Работодатель обязан:","children":[{"type":"subparagraph","number":"1","text":"обеспечивать исправное оборудование и необходимые средства защиты;"},{"type":"subparagraph","number":"2","text":"доводить до работника обязательные требования безопасности;"},{"type":"subparagraph","number":"3","text":"не допускать к опасной работе лицо, объективно не подготовленное к ней;"},{"type":"subparagraph","number":"4","text":"принимать разумные меры при выявлении угрозы жизни или здоровью;"},{"type":"subparagraph","number":"5","text":"организовывать обязательные медицинские осмотры там, где они требуются законом."}]}]},{"type":"article","number":"45","title":"Право отказаться от опасной работы","children":[{"type":"paragraph","number":"1","text":"Работник вправе отказаться от выполнения задания, если существует непосредственная и очевидная угроза его жизни или здоровью, а выполнение задания не относится к обязанностям по законному преодолению такой угрозы."},{"type":"paragraph","number":"2","text":"Военнослужащий, сотрудник правоохранительного органа, ФСБ, Следственного комитета, спасательной или медицинской службы не вправе ссылаться на обычный профессиональный риск как на основание отказа от законной обязанности, если данный риск свойственен службе и обеспечены предусмотренные законом меры защиты."},{"type":"paragraph","number":"3","text":"Отказ от заведомо незаконного приказа регулируется также уголовным законодательством и законодательством о государственной службе."}]},{"type":"article","number":"46","title":"Медицинские требования к работе","children":[{"type":"paragraph","number":"1","text":"Для отдельных видов труда закон или работодатель в пределах закона может устанавливать обязательное медицинское освидетельствование."},{"type":"paragraph","number":"2","text":"Просроченное обязательное медицинское заключение может являться основанием временного отстранения до прохождения осмотра."},{"type":"paragraph","number":"3","text":"Медицинские сведения работника являются информацией ограниченного доступа и используются только в необходимом объеме."}]},{"type":"article","number":"47","title":"Несчастный случай на работе","children":[{"type":"paragraph","number":"1","text":"О существенном несчастном случае, тяжелом ранении или иной угрозе жизни на работе работодатель обязан организовать оказание помощи и фиксацию обстоятельств."},{"type":"paragraph","number":"2","text":"При наличии признаков правонарушения материалы передаются компетентному государственному органу."},{"type":"paragraph","number":"3","text":"Работодатель не вправе скрывать сведения о несчастном случае с целью избежать законной ответственности."}]},{"type":"article","number":"48","title":"Специальные условия опасной службы","children":[{"type":"paragraph","text":"Федеральным законом могут устанавливаться специальные правила охраны труда, применения оружия, специальных средств, допуска к опасным объектам, медицинской пригодности и режима отдыха для военнослужащих, полиции, ГИБДД, ФСБ, Следственного комитета и иных специальных служб."}]},{"type":"article","number":"49","title":"Возмещение вреда здоровью","children":[{"type":"paragraph","text":"Вред, причиненный жизни или здоровью работника вследствие незаконных действий работодателя или грубого нарушения обязательных требований безопасности, подлежит возмещению в порядке, установленном федеральным законодательством или судом."}]}]}]},{"type":"section","number":"VI","title":"ТРУДОВАЯ ДИСЦИПЛИНА И ОТВЕТСТВЕННОСТЬ","children":[{"type":"chapter","number":"VII","title":"ПООЩРЕНИЯ, ДИСЦИПЛИНАРНЫЕ МЕРЫ И МАТЕРИАЛЬНАЯ ОТВЕТСТВЕННОСТЬ​","children":[{"type":"article","number":"50","title":"Трудовая дисциплина","children":[{"type":"paragraph","text":"Трудовой дисциплиной признается обязательность исполнения работником трудовых обязанностей, законных распоряжений работодателя, правил внутреннего трудового распорядка и требований федерального законодательства."}]},{"type":"article","number":"51","title":"Дисциплинарный проступок","children":[{"type":"paragraph","text":"Дисциплинарным проступком является виновное неисполнение или ненадлежащее исполнение работником трудовых обязанностей либо нарушение законного локального акта, если за соответствующее деяние не применяется иной специальный порядок ответственности."}]},{"type":"article","number":"52","title":"Дисциплинарные взыскания","children":[{"type":"paragraph","number":"1","text":"К работнику могут применяться:","children":[{"type":"subparagraph","number":"1","text":"замечание;"},{"type":"subparagraph","number":"2","text":"выговор;"},{"type":"subparagraph","number":"3","text":"строгий выговор, если такая мера предусмотрена локальным актом или специальным законодательством;"},{"type":"subparagraph","number":"4","text":"переаттестация, если она объективно связана с квалификацией работника;"},{"type":"subparagraph","number":"5","text":"понижение в должности при наличии согласия работника либо специального законного основания;"},{"type":"subparagraph","number":"6","text":"занесение в чёрный список;"},{"type":"subparagraph","number":"7","text":"увольнение."}]},{"type":"paragraph","number":"2","text":"В отношении государственного служащего применяются виды дисциплинарных взысканий, предусмотренные Федеральным законом «О государственной службе РО» и профильным законодательством. Настоящая статья не расширяет перечень специальных служебных взысканий."},{"type":"paragraph","number":"3","text":"В Вооруженных Силах и иных структурах со специальной дисциплиной федеральным законом могут устанавливаться дополнительные меры."},{"type":"note","text":"Дисциплинарное взыскание в виде занесения в чёрный список применяется исключительно в соответствии со статьёй 26 и пунктами 1, 2, 3, 4, 7 и 8 части 1 статьи 25 настоящего Кодекса."}]},{"type":"article","number":"53","title":"Порядок применения дисциплинарного взыскания","children":[{"type":"paragraph","number":"1","text":"Взыскание должно иметь конкретное фактическое основание."},{"type":"paragraph","number":"2","text":"До применения понижения или увольнения, если обстоятельства не являются очевидными и бесспорными, работнику должна быть предоставлена возможность дать объяснение."},{"type":"paragraph","number":"3","text":"Решение должно быть принято компетентным лицом и зафиксировано способом, позволяющим установить его содержание, основание и срок действия, если взыскание имеет срок."},{"type":"paragraph","number":"4","text":"За одно нарушение не допускается неоднократное применение нескольких самостоятельных дисциплинарных взысканий за одни и те же обстоятельства."},{"type":"paragraph","number":"5","text":"Дисциплинарная мера должна быть соразмерна характеру нарушения."}]},{"type":"article","number":"54","title":"Запрет неправомерного дисциплинарного преследования","children":[{"type":"paragraph","text":"Не допускается применять дисциплинарное взыскание исключительно за:","children":[{"type":"subparagraph","number":"1","text":"законное обжалование действий работодателя;"},{"type":"subparagraph","number":"2","text":"отказ от заведомо незаконного требования;"},{"type":"subparagraph","number":"3","text":"добросовестное сообщение о правонарушении;"},{"type":"subparagraph","number":"4","text":"обращение в прокуратуру или суд;"},{"type":"subparagraph","number":"5","text":"использование предусмотренного настоящим Кодексом права на отдых;"},{"type":"subparagraph","number":"6","text":"иное законное осуществление трудового права."}]}]},{"type":"article","number":"55","title":"Снятие дисциплинарного взыскания","children":[{"type":"paragraph","number":"1","text":"Работодатель вправе досрочно снять дисциплинарное взыскание по собственной инициативе, по просьбе работника или по представлению его руководителя."},{"type":"paragraph","number":"2","text":"Если после применения взыскания прошло не менее трех календарных дней, работник добросовестно исполнял обязанности и не допустил нового нарушения, работодатель вправе учитывать это как достаточное основание для досрочного снятия взыскания."},{"type":"paragraph","number":"3","text":"Специальным законом может быть установлен иной срок или порядок."}]},{"type":"article","number":"56","title":"Материальная ответственность работника","children":[{"type":"paragraph","number":"1","text":"Работник обязан возместить прямой действительный ущерб, виновно причиненный работодателю, если ответственность установлена законом, договором или судом."},{"type":"paragraph","number":"2","text":"Не подлежат взысканию предполагаемая упущенная выгода и обычный хозяйственный риск, если иное прямо не предусмотрено федеральным законом."},{"type":"paragraph","number":"3","text":"Размер и порядок возмещения определяются соглашением сторон либо судом."}]},{"type":"article","number":"57","title":"Материальная ответственность работодателя","children":[{"type":"paragraph","text":"Работодатель несет ответственность за незаконное лишение работника возможности трудиться, незаконное удержание заработной платы, причинение вреда имуществу работника и вред, причиненный нарушением обязательных требований охраны труда, в порядке, установленном законом или судом."}]}]}]},{"type":"section","number":"VII","title":"ОСОБЕННОСТИ ГОСУДАРСТВЕННОЙ СЛУЖБЫ И ПЕРЕВОДА","children":[{"type":"chapter","number":"VIII","title":"ТРУД ГОСУДАРСТВЕННЫХ СЛУЖАЩИХ​","children":[{"type":"article","number":"58","title":"Соотношение трудового законодательства и законодательства о государственной службе","children":[{"type":"paragraph","number":"1","text":"Государственный служащий пользуется общими трудовыми гарантиями, если они совместимы с характером государственной службы и не изменены специальным федеральным законом."},{"type":"paragraph","number":"2","text":"Поступление на службу, полномочия, служебная подчиненность, дисциплинарная ответственность, специальные и воинские звания, классные чины, применение оружия и специальные режимы службы регулируются профильным законодательством."},{"type":"paragraph","number":"3","text":"Трудовой кодекс не может толковаться как предоставляющий государственному служащему полномочия, не предусмотренные законом."},{"type":"paragraph","number":"4","text":"Вице Премьер-министр РО, федеральные министры, заместители федеральных министров и иные лица, замещающие государственные должности по назначению Премьер-министра РО, Вице Премьер-министра РО либо иного специально уполномоченного законом должностного лица, замещают такие должности на условиях специального публично-правового статуса."},{"type":"paragraph","number":"5","text":"Если федеральным законодательством предусмотрено свободное назначение и освобождение такого лица, прекращение его полномочий не требует предварительного дисциплинарного взыскания, служебной проверки, доказанности проступка или применения оснований увольнения, установленных для обычных трудовых отношений."},{"type":"paragraph","number":"6","text":"Освобождение лица от государственной должности не прекращает его обязанность передать государственное имущество, документы, сведения и дела в установленном порядке и не освобождает от ответственности за ранее совершенные правонарушения."}]},{"type":"article","number":"58.1","title":"Особые кадровые полномочия в системе Правительства РО","children":[{"type":"paragraph","number":"1","text":"Премьер-министр РО вправе назначать и освобождать от должности Вице Премьер-министра РО, федеральных министров, их заместителей и иных членов Правительства РО в случаях и порядке, предусмотренных федеральным законодательством. Такое решение может быть принято по кадровым, политическим, организационным или иным соображениям и не требует наличия дисциплинарного проступка."},{"type":"paragraph","number":"2","text":"Вице Премьер-министр РО вправе назначать и освобождать федеральных министров, первых заместителей и заместителей федеральных министров в случаях, когда такое полномочие прямо предоставлено ему федеральным законодательством."},{"type":"paragraph","number":"3","text":"Федеральный министр либо его заместитель вправе назначать и освобождать Руководителя аппарата министерства, руководителей структурных подразделений и иных должностных лиц центрального аппарата в пределах кадровых полномочий, установленных федеральным законодательством."},{"type":"paragraph","number":"4","text":"Освобождение лица от должности в соответствии с частями 1–3 настоящей статьи не требует применения процедуры дисциплинарного взыскания и не может быть признано незаконным исключительно вследствие отсутствия виновного проступка, неудовлетворительной оценки работы или иного обычного трудового основания."},{"type":"paragraph","number":"5","text":"Право свободного освобождения от должности не распространяется на должности, для которых Конституцией РО, федеральным конституционным законом или федеральным законом установлен специальный исчерпывающий порядок прекращения полномочий."},{"type":"paragraph","number":"6","text":"Акт о назначении или освобождении может быть обжалован в части наличия у принявшего его лица соответствующего полномочия, соблюдения обязательной процедуры и соответствия акту большей юридической силы. Кадровая, политическая или организационная целесообразность такого решения самостоятельному пересмотру по правилам обычного трудового спора не подлежит."},{"type":"paragraph","number":"7","text":"Освобождение от должности не прекращает обязанности по передаче государственных документов, имущества и дел, не аннулирует ранее наложенную ответственность и не препятствует привлечению лица к ответственности за совершенные до освобождения правонарушения."}]},{"type":"article","number":"59","title":"Служебный приказ и трудовые права","children":[{"type":"paragraph","number":"1","text":"Государственный служащий обязан исполнять законные служебные приказы."},{"type":"paragraph","number":"2","text":"Право на отдых не освобождает служащего от обязанности реагировать на реальную чрезвычайную или оперативную необходимость в случаях, предусмотренных законом."},{"type":"paragraph","number":"3","text":"Отказ от заведомо незаконного приказа не является трудовым или дисциплинарным проступком."}]},{"type":"article","number":"60","title":"Отстранение государственного служащего","children":[{"type":"paragraph","number":"1","text":"Отстранение государственного служащего осуществляется по основаниям и в порядке, установленным Федеральным законом «О государственной службе РО» и профильным законодательством."},{"type":"paragraph","number":"2","text":"Сам факт расследования или обвинения не означает автоматической виновности и не влечет обязательного увольнения."},{"type":"paragraph","number":"3","text":"Отстранение допускается, если дальнейшее исполнение полномочий создает существенный риск для проверки, сохранности государственного имущества, безопасности или законности."}]},{"type":"article","number":"61","title":"Межведомственный перевод","children":[{"type":"paragraph","number":"1","text":"Государственный служащий вправе обратиться с просьбой о переводе в другой государственный орган."},{"type":"paragraph","number":"2","text":"Перевод требует согласия руководителя либо иного компетентного должностного лица обеих государственных организаций, если специальным законом не установлен иной порядок."},{"type":"paragraph","number":"3","text":"При отсутствии руководителя решение вправе принять уполномоченный заместитель."},{"type":"paragraph","number":"4","text":"Премьер-министр РО или Правительство РО вправе согласовать перевод в пределах предоставленных им кадровых полномочий."},{"type":"paragraph","number":"5","text":"Перевод не означает автоматического сохранения конкретной должности, специального звания или полномочий, если профильным законодательством предусмотрен иной порядок."}]},{"type":"article","number":"62","title":"Должность при переводе","children":[{"type":"paragraph","number":"1","text":"Принимающий государственный орган определяет должность переводимого лица с учетом его квалификации, опыта, имеющегося звания или чина и вакантных должностей."},{"type":"paragraph","number":"2","text":"Если в обеих организациях применяется сопоставимый должностной табель, перевод по общему правилу не должен приводить к понижению более чем на пять должностных уровней без согласия служащего, если иное не обусловлено требованиями новой службы."},{"type":"paragraph","number":"3","text":"Специальные правила сохранения и присвоения званий определяются Федеральным законом «О специальных и воинских званиях и классных чинах»."}]},{"type":"article","number":"63","title":"Ограничения при государственной службе","children":[{"type":"paragraph","text":"Ограничения, связанные с судимостью, медицинской пригодностью, лицензиями, государственной тайной, конфликтом интересов и иными условиями поступления и прохождения государственной службы, устанавливаются уголовным законодательством, Федеральным законом «О государственной службе РО» и профильными федеральными законами."}]}]}]},{"type":"section","number":"VIII","title":"ЗАЩИТА ТРУДОВЫХ ПРАВ И ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","children":[{"type":"chapter","number":"IX","title":"ТРУДОВЫЕ СПОРЫ И ГОСУДАРСТВЕННЫЙ КОНТРОЛЬ​","children":[{"type":"article","number":"64","title":"Индивидуальный трудовой спор","children":[{"type":"paragraph","text":"Индивидуальным трудовым спором признается неурегулированное разногласие между работником и работодателем по вопросу применения трудового законодательства, трудового договора, локального акта, дисциплинарного взыскания, оплаты труда, перевода, отстранения или увольнения."}]},{"type":"article","number":"65","title":"Способы защиты трудовых прав","children":[{"type":"paragraph","text":"Работник вправе:","children":[{"type":"subparagraph","number":"1","text":"обратиться к работодателю или вышестоящему руководителю;"},{"type":"subparagraph","number":"2","text":"обратиться в прокуратуру РО;"},{"type":"subparagraph","number":"3","text":"обратиться в суд;"},{"type":"subparagraph","number":"4","text":"использовать иные предусмотренные федеральным законодательством способы защиты."}]}]},{"type":"article","number":"66","title":"Рассмотрение жалобы работодателем","children":[{"type":"paragraph","number":"1","text":"Работодатель обязан рассмотреть обращение работника в разумный срок."},{"type":"paragraph","number":"2","text":"Если обжалуется дисциплинарное взыскание, перевод, отстранение или увольнение, работодатель обязан проверить наличие компетенции, фактического основания и соблюдение процедуры."},{"type":"paragraph","number":"3","text":"Работодатель вправе отменить или изменить собственное незаконное решение."}]},{"type":"article","number":"67","title":"Полномочия прокуратуры в сфере труда","children":[{"type":"paragraph","number":"1","text":"Прокуратура осуществляет надзор за соблюдением трудового законодательства в соответствии с Федеральным законом «О прокуратуре РО»."},{"type":"paragraph","number":"2","text":"Прокурор вправе требовать необходимые документы, проводить проверку законности действий работодателя и применять предусмотренные законом акты прокурорского реагирования."},{"type":"paragraph","number":"3","text":"Прокурор не вправе произвольно подменять работодателя при решении обычных кадровых вопросов, если федеральным законом не предусмотрено иное."},{"type":"paragraph","number":"4","text":"Выявление признаков административного или уголовного правонарушения влечет передачу либо разрешение материала в порядке соответствующего кодекса."}]},{"type":"article","number":"68","title":"Судебная защита","children":[{"type":"paragraph","number":"1","text":"Суд вправе признать незаконными увольнение, дисциплинарное взыскание, отстранение, перевод, невыплату заработной платы или иной акт работодателя."},{"type":"paragraph","number":"2","text":"Суд вправе восстановить работника, отменить незаконный акт, взыскать причитающиеся денежные средства, присудить компенсацию и применить иной предусмотренный законом способ защиты."},{"type":"paragraph","number":"3","text":"Судебный акт обязателен для работодателя и работника."}]},{"type":"article","number":"69","title":"Государственная проверка работодателя","children":[{"type":"paragraph","number":"1","text":"Правительство РО и иные уполномоченные законом органы вправе проводить организационные проверки соблюдения трудового законодательства."},{"type":"paragraph","number":"2","text":"Проверка должна иметь законное основание и не может использоваться для незаконного вмешательства в деятельность суда, прокуратуры, Следственного комитета или иной процессуально самостоятельной структуры."},{"type":"paragraph","number":"3","text":"Работодатель обязан предоставить законно запрошенные документы, относящиеся к предмету проверки."}]},{"type":"article","number":"70","title":"Ответственность за нарушение трудового законодательства","children":[{"type":"paragraph","number":"1","text":"Нарушение настоящего Кодекса влечет дисциплинарную, материальную, административную, уголовную или иную ответственность при наличии предусмотренного законом основания."},{"type":"paragraph","number":"2","text":"Административная ответственность за нарушение трудового законодательства устанавливается Кодексом РО об административных правонарушениях Нормативно-правовой акт подписан Премьер-министром РО 27.09.2026 Марк Брагин ​"}]}]}]}]};
